/* ---------- typed model ---------- */
type Bag = Record<string, unknown>;
type Dict = Record<string, string>;
export type ClHist = { at: string; by: string; act: string; from?: string; to?: string; reason?: string; keptModified?: number };
export type ClCancel = { reason: string; note?: string; at: string; by: string };
export type ClExtP = { name: string; phone: string; email: string };
export type ClRemind = { chan: string[]; before: number[] };
/** A stored appointment, or a series occurrence computed on demand (series / occ / idx / modified set). */
export type ClAppt = {
  id: string; tenant: string; ver: number; idem?: string | null; status: string; start: string; end: string; tz: string; svc: string; pr: string; room: string | null; equip: string[];
  est: string | null; pid: string | null; ext: ClExtP | null; notesInt: string; instr: string; remind: ClRemind; conf: string; src?: string; created?: string; by?: string; hist: ClHist[];
  cancel?: ClCancel | null; synthetic?: boolean; arrived?: string; startedAt?: string; doneAt?: string; series?: string; occ?: string; idx?: number; modified?: boolean; [k: string]: unknown;
};
export type ClRule = { freq?: string; interval: number; byDay: number[]; until: string; count: number };
export type ClOv = { start?: string; end?: string; pr?: string; room?: string | null; status?: string; hist?: ClHist[]; cancel?: ClCancel; notesInt?: string; instr?: string; remind?: ClRemind; conf?: string; [k: string]: unknown };
export type ClTpl = { svc: string; pr: string; room: string | null; equip: string[]; est: string | null; pid: string | null; ext: ClExtP | null; notesInt: string; instr: string; remind: ClRemind; conf: string; tz: string; [k: string]: unknown };
export type ClSeries = { id: string; tenant: string; ver: number; idem: string | null; status: string; startDate: string; time: string; tz: string; dur: number; rule: ClRule; ex: string[]; ov: Record<string, ClOv>; tpl: ClTpl; created: string; by: string; hist: ClHist[]; cancel?: Omit<ClCancel, "note"> };
export type ClAvailT = { id: string; tenant: string; pr: string; est: string; week: Record<string, [string, string, string?][]>; maxPerDay: number };
/** An availability exception; Calendar & Planning records its internal events with a group, an event kind, a room and its source. */
export type ClExc = { id: string; tenant: string; pr: string; est?: string; kind: string; from: string; to: string; start?: string; end?: string; reason: string; by?: string; at?: string; grp?: string; evt?: string; room?: string | null; src?: string };
