export type ClRes = { id: string; tenant: string; kind: string; n: string; est: string; type: string; cap: number; attrs: string[]; active: boolean; maint: ClMaint[] };
export type ClExtEv = { id: string; tenant: string; uid: string; pr: string; acc: string; title: string; start: string; end: string; rrule: string; imported: string; upd?: string };
export type ClSync = { at: string; by: string; pr: string; add: number; upd: number; skip: number; rm: number; n: number; ok: boolean; err?: string };
export type ClNotif = { id: string; key: string; tenant: string; appt: string; kind: string; chan: string; to: string; status: string; why: string; attempts: number; created: string; due: string; sentAt?: string; sim?: boolean; retryAt?: string };
export type ClLink = { id: string; tenant: string; token: string; label: string; svcs: string[]; prs: string[]; est: string; expires: string; created: string; by: string; active: boolean; uses: number; max: number; revoked?: string };
export type ClAudit = { id: string; ts: string; tenant: string; role: string; user: string; act: string; ref: string; detail: string };
export type ClPol = { minNotice: number; window: number; cancelNotice: number; allowExt: boolean; step: number; simFail: boolean; [k: string]: unknown };
