export type ClState = {
  v: number; synthetic: boolean; tenant: string; role: string; me: string; rev: number; seeded: string; appts: ClAppt[]; series: ClSeries[]; avail: ClAvailT[]; exc: ClExc[]; res: ClRes[];
  ext: ClExtEv[]; syncRuns: ClSync[]; outbox: ClNotif[]; links: ClLink[]; audit: ClAudit[]; pol: ClPol; prefs: ClPrefs; billSkips?: { appt: string; at: string; miss: string[] }[]; [k: string]: unknown;
};
export type ClRec = { interval?: number; byDay?: number[]; until?: string; count?: number; ex?: string[] };
/** Booking input (wizard draft, public booking, duplicate). */
export type ClDraft = { id?: string; pid?: string | null; ext?: ClExtP | null; svc?: string | null; pr?: string; room?: string | null; equip?: string[]; est?: string | null; start?: string; end?: string | null; status?: string; remind?: ClRemind; notesInt?: string; instr?: string; idem?: string | null; tz?: string; conf?: string; src?: string; series?: string; occ?: string; ver?: number; rec?: ClRec | null; public?: boolean; hp?: string; consent?: boolean; dur?: number; [k: string]: unknown };
