type ClLane = { a: ClAppt; s: number; e: number; lane?: number; n?: number };
type ClWiz = { mode: string; pid: string; ext: ClExtP; q: string; svc: string; prMode: string; pr: string; team: string; est: string; room: string; equip: string[]; from: string; slot: (Omit<ClSlot, "warn"> & { warn?: ClConf[] }) | null; dur: number;
  rec: { on: boolean; interval: number | string; byDay: number[]; count: number | string; until: string; ex: string[]; skip: boolean }; status: string; remind: ClRemind; notesInt: string; instr: string; idem: string; seenRev: number; force: boolean; reason: string; manual: string; step?: number; title?: string; slotsAt?: number; [k: string]: unknown };
