type ClIcsDt = { date?: string; allDay?: boolean; iso?: string | null; local?: string; tz?: string };
type ClIcsRaw = { uid?: string; title?: string; ds?: ClIcsDt; de?: ClIcsDt; rrule?: string; status?: string; transp?: string };
type ClPrev = { k: string; ex?: boolean; gap?: boolean; start?: string; fold?: boolean; conf?: ClConf[] };
/** clBook's result: a booked appointment, a series, or the earlier booking of a resent request (`dup`). */
type ClBookR = { dup?: boolean; series?: boolean; item: ClAppt & ClSeries; warn?: ClConf[]; excluded?: { k: string; msg: string }[] };
type ClDrag = { ev: HTMLElement; a: ClAppt; x0: number; y0: number; on: boolean; top0: number; pid: number; ghost?: HTMLElement; target?: { date: string; min: number; colid?: string; kind?: string } };
/** Payload of the appointment / resource events on the bus (clEmitAppt, Cabinet's resource events). */
type ClEvP = { appt: string; pr: string; pid: string | null; start: string; end: string; svc: string; room: string | null; est: string | null; status: string; rid: string; from: string; to: string; reason?: string; of?: string };
