const toast = (m: string) => useShell.getState().showToast(m);
const osMenu = (x: number, y: number, items: (MenuItem | string | null)[]) => osMenuCore(x, y, items as MenuItem[]);
const OS_USER = null as { name?: string } | null;
/** OSW.calendar / OSW.cabinet: open windows, found through the window manager. */
const OSW = { get calendar() { return clWinEl() ? { el: clWinEl()! } : null; }, get cabinet() { return useWm.getState().wins.cabinet ? {} : null; } };
/** OSW.calendar.el (the window) — found by its key. */
const clWinEl = () => document.querySelector<HTMLElement>('.os-win[data-osw="calendar"]');
