function clItems(from: number,to: number,o: { active?: boolean }={}){const S=clSt();const out=S.appts.filter(a=>clT(a)&&clOverlap(Date.parse(a.start),Date.parse(a.end),from,to));S.series.filter(clT).forEach(sr=>clSeriesOcc(sr,from,to).forEach(oc=>out.push(oc)));return o.active?out.filter(a=>CL_ACTIVE(a.status)):out}
