  if(c.pid)items.filter(a=>a.pid===c.pid).forEach(a=>{if(clOverlap(s0,e0,Date.parse(a.start),Date.parse(a.end)))add("patient","warn",L4("Le patient a déjà un rendez-vous sur ce créneau|Patient already has an appointment then|Patient hat bereits einen Termin|للمريض موعد آخر")+" ("+clFmtT(a.start)+")")});
  const P=S.pol;const now=clNow();if(!o.staffSkipNotice||o.public){if(s0<now)add("past",o.public?"block":"warn",L4("Créneau dans le passé|Slot in the past|Zeitfenster in der Vergangenheit|موعد في الماضي"));else if(s0-now<(P.minNotice||0)*3600000)add("notice",o.public?"block":"warn",L4("Délai de prévenance minimal non respecté|Minimum notice not met|Mindestvorlauf unterschritten|لم يُحترم الإشعار الأدنى")+` (${P.minNotice} h)`);if(s0-now>(P.window||90)*864e5)add("window",o.public?"block":"warn",L4("Au-delà de la fenêtre de réservation|Beyond the booking window|Außerhalb des Buchungsfensters|خارج نافذة الحجز")+` (${P.window} j)`)}
