function clGo(view: string,arg?: string | null,o: { noStack?: boolean }={}){const R=clRoot();if(!CL_P[view])return;if(!clPageOk(CL_P[view])){clToast(clW("denied"),null,"err");return}if(!o.noStack&&(CL.ui.view!==view||arg!==undefined)){CL.ui.stack.push([CL.ui.view,CL.ui.arg]);if(CL.ui.stack.length>30)CL.ui.stack.shift()}CL.ui.view=view;CL.ui.arg=arg??null;CL.ui.navOpen=false;clDrawer(null);if(!R)return;
  const swap=()=>{R.querySelector<HTMLInputElement>(".hr-bar")!.outerHTML=clBarHTML();const pg=R.querySelector<HTMLInputElement>(".hr-pg");pg!.dataset.pg=view;pg!.innerHTML=clPageHTML();pg!.scrollTop=0;R.querySelector<HTMLInputElement>(".hr-nav")!.outerHTML=clNavHTML();R.querySelector<HTMLInputElement>(".hr-scrim")!.classList.remove("on");clMount();requestAnimationFrame(()=>clInk(true));clEnter(pg)};const pg=R.querySelector<HTMLInputElement>(".hr-pg");if(pg&&!hrRM())pg.animate([{opacity:1},{opacity:0}],{duration:100}).finished.then(swap).catch(swap);else swap()}
function clBack(){const p=CL.ui.stack.pop();if(p)clGo(p[0],p[1],{noStack:true})}
function clRefresh(){const R=clRoot();if(!R)return;const pg=R.querySelector<HTMLInputElement>(".hr-pg");const st=pg!.scrollTop;const gs=pg!.querySelector<HTMLInputElement>(".cl-gscroll");const gst=gs?.scrollTop;pg!.innerHTML=clPageHTML();pg!.scrollTop=st;const g2=pg!.querySelector<HTMLInputElement>(".cl-gscroll");if(g2&&gst!=null)g2.scrollTop=gst;R.querySelector<HTMLInputElement>(".hr-nav")!.outerHTML=clNavHTML();R.querySelector<HTMLInputElement>(".hr-bar")!.outerHTML=clBarHTML();clMount();clInk(false);if(CL.ui.drawer)clDrawerPaint()}
function clToast(msg: string,undo?: (() => void) | null,kind?: string){const R=clRoot();const el: HTMLElementX | null | undefined=R?.querySelector<HTMLInputElement>(".hr-toast");if(!el){typeof toast==="function"&&toast(msg);return}el.innerHTML=`${hri(kind==="err"?"alert":"check",15)}<span>${hrE(msg)}</span>${undo?`<button type="button" class="hr-lnk">${hrE(L4("Annuler|Undo|Rückgängig|تراجع"))}</button>`:""}`;el.classList.toggle("bad",kind==="err");el.classList.add("on");if(undo)el.querySelector<HTMLInputElement>("button")!.onclick=()=>{undo();el.classList.remove("on")};clearTimeout(el._t);el._t=setTimeout(()=>el.classList.remove("on"),undo?6000:2800)}
function clAct<T>(fn: () => T,msg?: string){try{const r=fn();clRefresh();if(msg)clToast(msg);return r??true}catch(e){clToast(clErr(e),null,"err");return null}}
function clDialog(title: string,body: string,o: DlgOpts={}){const R=clRoot();if(!R)return null;R.querySelector<HTMLInputElement>(".hr-dlg")?.remove();const m: HTMLElementX=document.createElement("div");m.className="hr-dlg";const back=document.activeElement as HTMLElement | null;m.innerHTML=`<form class="bx${o.wide?" wide":""}${o.xl?" xl":""}" role="dialog" aria-modal="true" aria-label="${hrE(title)}" novalidate><header><b>${o.icon?hri(o.icon,17):""}${hrE(title)}</b><button type="button" class="hr-ib sm" data-x aria-label="${hrE(clW("close"))}">${hri("x",15)}</button></header><div class="bd">${body}</div><p class="hr-err sm" data-dlgerr hidden></p><footer>${o.foot||""}<span class="sp"></span>${o.cancel!==false?`<button type="button" class="hr-btn" data-x>${hrE(o.cancelLabel||clW("cancel"))}</button>`:""}${o.ok!==false?`<button type="submit" class="hr-btn ${o.danger?"danger-pri":"pri"}">${hrE(o.okLabel||clW("ok"))}</button>`:""}</footer></form>`;R.appendChild(m);
  const close=()=>{const done=()=>{m.remove();if(back&&document.contains(back))back.focus?.({preventScroll:true})};if(hrRM())done();else m.animate([{opacity:1},{opacity:0}],{duration:140}).finished.then(done)};m._close=close;m.querySelectorAll<HTMLInputElement>("[data-x]").forEach(b=>b.onclick=close);
  m.addEventListener("keydown",e=>{if(e.key==="Escape"){e.stopPropagation();close()}if(e.key==="Tab"){const f=[...m.querySelectorAll<HTMLInputElement>("button,input,select,textarea,a[href],[tabindex]:not([tabindex='-1'])")].filter(x=>!x.disabled&&x.offsetParent);if(!f.length)return;const a=f[0],z=f[f.length-1];if(e.shiftKey&&document.activeElement===a){e.preventDefault();z.focus()}else if(!e.shiftKey&&document.activeElement===z){e.preventDefault();a.focus()}}});
  m.querySelector<HTMLInputElement>("form")!.onsubmit=e=>{e.preventDefault();const er=m.querySelector<HTMLInputElement>("[data-dlgerr]");er!.hidden=true;try{const r=o.onOk?o.onOk(m):true;if(r!==false)close()}catch(err){er!.innerHTML=hrE(clErr(err))+((err as ClErr)?.o?.alts?.length?clAltsHTML((err as ClErr).o!.alts!):"");er!.hidden=false;if(!hrRM())er!.animate([{transform:"translateX(-5px)"},{transform:"translateX(5px)"},{transform:"none"}],{duration:240})}};
  setTimeout(()=>(m.querySelector<HTMLInputElement>("[autofocus]")||m.querySelector<HTMLInputElement>("input:not([type=hidden]),select,textarea,button[type=submit]")||m.querySelector<HTMLInputElement>("[data-x]"))?.focus(),40);o.mount?.(m);return m}
