function clAvailSave(pr: string,week: ClAvailT["week"],maxPerDay: number | string){if(!(clCan("avail.all")||(clCan("avail.own")&&pr===clMe())))throw new ClErr("cl_eDenied");const S=clSt();let a=clAvail(pr);Object.values(week).forEach(rs=>rs.forEach(([s,e])=>{if(!/^\d{2}:\d{2}$/.test(s)||!/^\d{2}:\d{2}$/.test(e)||clMin(e)<=clMin(s))throw new ClErr("cl_eInvalid",s+"–"+e)}));if(!a){a={id:"av-"+pr,tenant:clTenant(),pr,est:"",week:{},maxPerDay:0};S.avail.push(a)}a.week=week;a.maxPerDay=+maxPerDay||0;clLog("avail.save",pr,Object.keys(week).length+" j");clSave();return clImpacted(pr)}
function clExcAdd(x: Partial<ClExc>){const org=x.pr==="*";if(org?!clCan("avail.all"):!(clCan("avail.all")||(clCan("avail.own")&&x.pr===clMe())))throw new ClErr("cl_eDenied");if(!x.from||!x.to||x.to<x.from)throw new ClErr("cl_eInvalid",L4("dates|dates|Daten|التواريخ"));if((x.start&&!x.end)||(x.start&&clMin(x.end!)<=clMin(x.start)))throw new ClErr("cl_eInvalid",L4("heures|times|Zeiten|الأوقات"));const S=clSt();const e=Object.assign({id:clId("x"),tenant:clTenant(),by:clUser(),at:clIso(Date.now())},x);S.exc.push(e as ClExc);clLog("avail.exception",x.pr,x.kind+" "+x.from+"→"+x.to);clSave();return {exc:e,impacted:clImpacted(org?null:x.pr!,x.from,x.to)}}
function clExcDel(id: string){const S=clSt();const x=S.exc.find(e=>e.id===id&&clT(e));if(!x)throw new ClErr("cl_eNotFound");if(x.pr==="*"?!clCan("avail.all"):!(clCan("avail.all")||(clCan("avail.own")&&x.pr===clMe())))throw new ClErr("cl_eDenied");S.exc.splice(S.exc.indexOf(x),1);clLog("avail.exceptionRemoved",x.pr,x.kind+" "+x.from);clSave();return x}
