function clImpacted(pr: string | null,from?: string,to?: string){const f=from?clZms(from,"00:00",CL_ORG_TZ):clNow(),t=to?clZms(clAddD(to,1),"00:00",CL_ORG_TZ):clNow()+60*864e5;return clItems(Math.max(f,clNow()),t,{active:true}).filter(a=>(!pr||a.pr===pr)&&!["completed","inprogress"].includes(a.status)&&clConflictsOf(a).length)}
