  if((x=c("[data-cltog]"))){const g=x.dataset.cltog;CL.ui.open[g!]=CL.ui.open[g!]===false;x.closest<HTMLInputElement>(".hr-ns")!.classList.toggle("open");x.setAttribute("aria-expanded",String(CL.ui.open[g!]!==false));(x.nextElementSibling as HTMLElement).hidden=CL.ui.open[g!]===false;clInk(true);return}
