  if((x=c("[data-clrole]"))){const r=x.getBoundingClientRect();osMenu(Math.max(8,r.right-290),r.bottom+4,[{html:`<div class="hr-menuh">${hrE(clW("role"))}</div>`},...Object.entries(CL_ROLES).map(([k,v])=>({l:L4(v.n),check:clRole()===k,run:()=>{clSt().role=k;clLog("role.switch","",k);clSave();CL.ui.stack=[];CL.ui.flt.pr=null;clRender(true);clToast(clW("role")+" : "+L4(v.n))}})),"-",{l:L4("Praticien·ne simulé·e : |Simulated practitioner: |Simulierte(r) Behandler(in): |الممارس المحاكى: ")+rmPracName(clMe()),sub:rmPracs().map(p=>({l:rmPracName(p),check:clMe()===p.id,run:()=>{clSt().me=p.id;clSave();clRender(false)}}))}]);return}
  if(c("[data-clnew]")){clWizard({from:CL.ui.date&&CL.ui.date>clToday()?CL.ui.date:clToday()});return}
  if((x=c("[data-clquick]"))){const q=JSON.parse(x.dataset.clquick!);clWizard({pr:q.pr,from:clDateOf(Date.parse(q.start),clTz())});return}
  if((x=c("[data-clev]"))&&!c(".cl-ev.drag")){clDrawer(x.dataset.clev!);return}if(c("[data-cldx]")){clDrawer(null);return}
  if((x=c("[data-clnavd]"))){const n=+x.dataset.clnavd!;const m=CL.ui.mode;if(!n)CL.ui.date=clToday();else CL.ui.date=m==="month"?(()=>{const d=new Date(clAnchor().slice(0,8)+"01T12:00:00Z");d.setUTCMonth(d.getUTCMonth()+n);return d.toISOString().slice(0,10)})():clAddD(clAnchor(),n*(m==="day"?1:m==="agenda"?14:7));clSwap(n);return}
  if((x=c("[data-clmode]"))){CL.ui.mode=x.dataset.clmode!;clSt().prefs.mode=CL.ui.mode;clSave(false);clSwap(0);return}if((x=c("[data-clby]"))){CL.ui.by=x.dataset.clby!;clSwap(0);return}
  if((x=c("[data-clday]"))){CL.ui.date=x.dataset.clday!;if(x.dataset.clmodego)CL.ui.mode=x.dataset.clmodego;clSwap(0);return}
  if((x=c("[data-clmini]"))){const d=new Date(clAnchor().slice(0,8)+"01T12:00:00Z");d.setUTCMonth(d.getUTCMonth()+ +x.dataset.clmini!);CL.ui.date=d.toISOString().slice(0,10);clSwap(+x.dataset.clmini!);return}
  if((x=c("[data-clteam]"))){CL.ui.flt.team=CL.ui.flt.team===x.dataset.clteam?"":x.dataset.clteam;if(clRole()==="clin")CL.ui.flt.mine=false;clRefresh();return}
  if(c("[data-clfilt]")){CL.ui.fopen=!CL.ui.fopen;clRefresh();return}if(c("[data-clfreset]")){CL.ui.flt={pr:null};clRefresh();return}
  if(c("[data-clshowconf]")){const its=clVisItems(clRange()).filter(a=>clConflictsOf(a).length);clImpactNotice(its);return}
  if((x=c("[data-clprefs]"))){const r=x.getBoundingClientRect();const P=clSt().prefs;osMenu(Math.max(8,r.right-260),r.bottom+4,[{html:`<div class="hr-menuh">${hrE(L4("Affichage|Display|Anzeige|العرض"))}</div>`},{l:L4("Afficher les annulés|Show cancelled|Stornierte anzeigen|إظهار الملغاة"),check:!!P.showCancelled,run:()=>{P.showCancelled=!P.showCancelled;clSave(false);clRefresh()}},"-",...([[.8,"Compacte|Compact|Kompakt|مضغوط"],[1,"Standard|Standard|Standard|عادي"],[1.4,"Large|Large|Groß|كبير"]] as [number, string][]).map(([z,l])=>({l:L4(l),check:P.zoom===z,run:()=>{P.zoom=z;clSave(false);clRefresh()}})),"-",{l:L4("Fuseau d’affichage : |Display zone: |Zeitzone: |المنطقة: ")+P.tz,sub:CL_TZS.map(z=>({l:z,check:P.tz===z,run:()=>{P.tz=z;clSave(false);clRefresh();clToast(L4("Fuseau d’affichage : |Display zone: |Zeitzone: |المنطقة: ")+z)}}))}]);return}
  if((x=c("[data-clst]"))){const id=CL.ui.drawer;const to=x.dataset.clst;clAct(()=>clSetStatus(id!,to!),L4(CL_STATUS[to!]));if(CL.ui.drawer)clDrawerPaint();return}
