  if((x=c("[data-clagpr]"))){CL.ui.flt={pr:[x.dataset.clagpr!],mine:false};CL.ui.mode="week";clGo("agenda");return}if((x=c("[data-clpday]"))){CL.ui.pdate=x.dataset.clpday;clRefresh();return}
  if((x=c("[data-radd]"))){const box=R.querySelector<HTMLInputElement>(`.cl-ranges[data-wd="${x.dataset.radd}"]`);box!.querySelector<HTMLInputElement>(".hr-mut")?.remove();const ests=rmEsts().slice(0,2);box!.insertAdjacentHTML("beforeend",`<span class="cl-range"><input type="time" class="hr-in sm" value="09:00" data-rs step="900" aria-label="${hrE(L4("Début|Start|Beginn|البداية"))}"><span>→</span><input type="time" class="hr-in sm" value="12:00" data-re step="900" aria-label="${hrE(L4("Fin|End|Ende|النهاية"))}"><select class="hr-in sm" data-rest aria-label="${hrE(L4("Établissement|Establishment|Einrichtung|المؤسسة"))}">${clOpts(ests.map(e=>[e.id,e.n]),(clAvail(CL.ui.avpr!)||{}).est||"s1")}</select><button type="button" class="hr-ib sm" data-rdel aria-label="${hrE(L4("Retirer|Remove|Entfernen|إزالة"))}">${hri("x",13)}</button></span>`);box!.lastElementChild!.querySelector<HTMLInputElement>("input")!.focus();return}
