  if((x=c("[data-clextdel]"))){clAct(()=>{clNeed("sync.manage");const S=clSt();const i=S.ext.findIndex(y=>y.id===x!.dataset.clextdel);if(i>=0){clLog("sync.remove",S.ext[i].pr,S.ext[i].uid);S.ext.splice(i,1)}clSave()},clW("saved"));return}
  if(c("[data-cllinknew]")){clLinkDlg();return}if((x=c("[data-cllinkrv]"))){clConfirm(L4("Le lien cessera de fonctionner immédiatement.|The link will stop working immediately.|Link wird sofort ungültig.|سيتوقف الرابط فورًا."),()=>clAct(()=>clLinkRevoke(x!.dataset.cllinkrv!),clW("saved")),{danger:true});return}
